insert into public.products (slug, category_slug, name, description, price, stock, image_url, specs) values
('arduino-uno-r3', 'boards', '아두이노 우노 R3 정품 (Arduino Uno R3, A000066)', 'ATmega328P 기반의 이탈리아 정품 아두이노 우노 R3로, 입문부터 프로토타이핑까지 가장 널리 쓰이는 표준 보드입니다.', 31900, 173, '/images/products/arduino-uno-r3.jpg', '{"MCU":"ATmega328P","동작전압":"5V","디지털 I/O":"14핀 (PWM 6)","아날로그 입력":"6핀","크기":"68.6 x 53.4mm"}'::jsonb),
('arduino-nano', 'boards', '아두이노 나노 호환보드 CH340', 'CH340 USB 칩을 사용한 아두이노 나노 100% 호환보드로, 브레드보드에 바로 꽂아 쓰는 소형 보드입니다.', 6050, 38, '/images/products/arduino-nano.jpg', '{"MCU":"ATmega328P","USB 칩":"CH340","동작전압":"5V","입력전압":"7~12V","크기":"18 x 45mm"}'::jsonb),
('arduino-mega-2560', 'boards', '아두이노 메가 2560 R3 정품 (A000067)', 'ATmega2560 기반의 정품 메가 보드로, 54개의 디지털 핀과 넉넉한 메모리로 대형 프로젝트에 적합합니다.', 64900, 16, '/images/products/arduino-mega-2560.jpg', '{"MCU":"ATmega2560","동작전압":"5V","디지털 I/O":"54핀 (PWM 15)","아날로그 입력":"16핀","플래시 메모리":"256KB"}'::jsonb),
('esp32-devkit', 'boards', 'ESP32 DevKitC WROOM-32D V4 개발보드 (CH9102X)', 'Wi-Fi와 블루투스를 모두 지원하는 듀얼코어 ESP32 개발보드로, IoT 프로젝트에 최적입니다.', 8690, 199, '/images/products/esp32-devkit.jpg', '{"모듈":"ESP32-WROOM-32D","CPU":"듀얼코어 최대 240MHz","무선":"Wi-Fi 802.11 b/g/n + Bluetooth","USB 칩":"CH9102X (마이크로 5핀)","입력전압":"5V (USB)"}'::jsonb),
('hc-sr04', 'sensors', '초음파 거리센서 모듈 HC-SR04', '초음파를 이용해 2cm~500cm 거리의 물체를 비접촉으로 측정하는 대표적인 거리센서입니다.', 1210, 80, '/images/products/hc-sr04.jpg', '{"동작전압":"DC 5V","측정거리":"2cm ~ 500cm","측정각도":"약 15°","정밀도":"약 3mm","크기":"45 x 20 x 15mm"}'::jsonb),
('dht11', 'sensors', 'DHT11 온습도 센서모듈', '보정된 디지털 신호로 온도와 습도를 동시에 측정하는 저전력 온습도 센서 모듈입니다(케이블 포함).', 1760, 72, '/images/products/dht11.jpg', '{"동작전압":"3.3V ~ 5V","온도 측정범위":"0 ~ 50℃ (±2℃)","습도 측정범위":"20 ~ 90%RH (±5%)","출력":"단일 버스 디지털"}'::jsonb),
('hc-sr501', 'sensors', '인체감지 PIR 센서모듈 HC-SR501', '적외선 변화를 감지해 사람의 움직임을 인식하는 PIR 센서로, 감도와 지연시간을 조절할 수 있습니다.', 1650, 67, '/images/products/hc-sr501.jpg', '{"동작전압":"DC 5V ~ 20V","감지거리":"최대 약 7m (조절 가능)","감지각도":"약 120°","출력":"디지털 High 3.3V / Low 0V","크기":"32 x 24mm"}'::jsonb),
('cds-sensor', 'sensors', 'CdS 조도센서(광센서) 모듈', 'CdS 광저항과 LM393 비교기를 이용해 주변 밝기를 측정하는 조도센서 모듈입니다.', 1540, 45, '/images/products/cds-sensor.jpg', '{"동작전압":"3.3V / 5V","센서":"CdS 광저항","비교기":"LM393","출력":"디지털(DO) + 아날로그(AO)","크기":"32 x 14mm"}'::jsonb),
('sg90-servo', 'modules', '9g 미니 서보모터 SG90 (TowerPro 호환)', '작고 가벼운 대표 미니 서보모터로, 0~180° 각도 제어가 필요한 로봇·RC 프로젝트에 사용됩니다.', 2090, 198, '/images/products/sg90-servo.jpg', '{"동작전압":"4.8V ~ 6V","토크":"1.8kg·cm (4.8V)","속도":"0.1초/60° (4.8V)","회전각":"약 180°","무게":"9g"}'::jsonb),
('relay-module', 'modules', '아두이노 1채널 5V 릴레이 모듈', '아두이노 신호로 최대 AC 250V/10A 부하를 on/off 할 수 있는 1채널 5V 릴레이 모듈입니다.', 1210, 36, '/images/products/relay-module.jpg', '{"코일 전압":"DC 5V","최대 부하":"AC 250V/10A, DC 30V/10A","채널":"1채널","크기":"50 x 26 x 18.5mm"}'::jsonb),
('lcd-1602-i2c', 'modules', '아두이노 I2C 1602 LCD 모듈', 'I2C 변환 모듈이 부착되어 4개의 선만으로 연결 가능한 16x2 캐릭터 LCD입니다.', 2750, 183, '/images/products/lcd-1602-i2c.jpg', '{"표시":"16 x 2 문자","인터페이스":"I2C (PCF8574)","동작전압":"5V","백라이트":"Blue 백라이트 / White 문자","크기":"80 x 36mm"}'::jsonb),
('l298n', 'modules', 'L298N 2A 듀얼 모터드라이버 모듈', 'L298N 칩을 탑재한 듀얼 H-브리지 모터드라이버로, DC 모터 2개 또는 스테핑 모터 1개를 제어합니다.', 2970, 199, '/images/products/l298n.jpg', '{"드라이버 IC":"L298N (Dual H-Bridge)","구동 전압":"5V ~ 35V","최대 전류":"2A (채널당)","로직 전압":"5V","채널":"DC 모터 2개"}'::jsonb),
('breadboard-830', 'parts', '브레드보드 830홀 MB-102', '납땜 없이 회로를 구성할 수 있는 표준 830홀 규격 브레드보드입니다.', 1540, 149, '/images/products/breadboard-830.jpg', '{"홀 수":"830홀","규격":"MB-102","크기":"165 x 55 x 8.5mm","핀 간격":"2.54mm"}'::jsonb),
('jumper-wires', 'parts', '점퍼 케이블 40P 세트 (M/M, 20cm)', '브레드보드와 아두이노 연결에 쓰는 40가닥 컬러 점퍼 케이블 세트입니다.', 935, 32, '/images/products/jumper-wires.jpg', '{"구성":"40가닥","타입":"Male-Male","길이":"20cm","커넥터 간격":"2.54mm"}'::jsonb),
('led-kit', 'parts', '5mm 원형 LED 키트 (5색 200개)', '빨강·초록·파랑·노랑·흰색 5mm LED 200개로 구성된 회로 실습용 LED 세트입니다.', 3300, 161, '/images/products/led-kit.jpg', '{"크기":"5mm 원형","구성":"5색 x 40개 = 200개","순방향 전압":"약 2V ~ 3.2V","정격 전류":"20mA"}'::jsonb),
('starter-kit', 'kits', '아두이노 스타터 키트 한글판 정품 (K120007)', '정품 아두이노 우노와 다양한 전자부품, 15가지 프로젝트가 수록된 한글 가이드북이 포함된 공식 입문 키트입니다.', 152900, 118, '/images/products/starter-kit.jpg', '{"포함 보드":"Arduino Uno","프로젝트":"15가지 (한글 가이드북)","동작전압":"5V","구성":"브레드보드, 센서, 모터, LED 등 기초 부품"}'::jsonb);
